export function buildUrl(base, path = '', ...segments) {
  let url = base.endsWith('/') ? base.slice(0, -1) : base;
  if (path !== '') url += '/' + path;
  for (const seg of segments) {
    url += '/' + seg;
  }
  return url;
}

