bootforge/js-fundamentals/functions/scop.solution:
export function makeAccount(initial) {
  let balance = initial;
  return {
    deposit(amount) {
      if (amount > 0) balance += amount;
      return balance;
    },
    withdraw(amount) {
      if (amount <= 0 || amount > balance) return null;
      balance -= amount;
      return balance;
    },
    getBalance() {
      return balance;
    },
  };
}
